#!/usr/bin/env bash
# facedoor first-boot installer (runs on the Pi as root from facedoor-firstboot.service).
# Owner: hw-engineer. STATUS: UNVERIFIED ON REAL HARDWARE (bash -n and PC review only).
#
# Installed by cloud-init (user-data runcmd) from /boot/firmware/facedoor-firstboot.sh to
# /usr/local/sbin/facedoor-firstboot. Settings come from /etc/facedoor/firstboot.env (written by
# cloud-init write_files; generated by deploy/sdcard/sdcard_tool.py stage).
#
# Steps (idempotent: every step can be re-run; the service runs on each boot until it succeeds):
#   1. wait for name resolution (apt/pip need the network), up to FACEDOOR_NET_TIMEOUT seconds
#   2. verify the bundle sha256 against <bundle>.sha256 (written on the PC at staging time)
#   3. extract into FACEDOOR_DIR (ASCII path, default /opt/facedoor) unless the same bundle is already there,
#      after checking that every tar member is under facedoor/ and verifying MANIFEST.sha256
#   4. configs/local.yaml: hardware.mode pi (FACEDOOR_SET_PI_MODE=1) or mock
#   5. deploy/install_rpi.sh --user <user> [--no-service] [--no-models]   (never --start)
#   6. write /var/lib/facedoor/firstboot.done and disable this unit
#
# Safety: this script NEVER touches GPIO. It does not run hw_selftest.py and does not start
# facedoor.service; the solenoid output stays at whatever the boot state is (OFF with correct wiring,
# see deploy/WIRING.md). With FACEDOOR_ENABLE_SERVICE=1 the service is enabled and starts on the next boot.
#
# On failure: the reason is logged to /var/log/facedoor-firstboot.log (and the journal) and to
# /var/lib/facedoor/firstboot.failed; exit status is non-zero; the unit stays enabled -> retried next boot.
#
# Manual use:  sudo /usr/local/sbin/facedoor-firstboot        (re-run; no-op if already done)
#              sudo /usr/local/sbin/facedoor-firstboot --force (ignore the done marker)
set -uo pipefail
umask 022

ENV_FILE="${FACEDOOR_FIRSTBOOT_ENV:-/etc/facedoor/firstboot.env}"
STATE_DIR="${FACEDOOR_STATE_DIR:-/var/lib/facedoor}"
LOG_FILE="${FACEDOOR_FIRSTBOOT_LOG:-/var/log/facedoor-firstboot.log}"
DONE_MARKER="$STATE_DIR/firstboot.done"
FAIL_MARKER="$STATE_DIR/firstboot.failed"
LOCK_FILE="/run/facedoor-firstboot.lock"
STAMP_NAME=".facedoor-bundle.sha256"
FORCE=0

for arg in "$@"; do
  case "$arg" in
    --force) FORCE=1 ;;
    -h|--help) sed -n '2,27p' "$0"; exit 0 ;;
    *) echo "unknown option: $arg" >&2; exit 2 ;;
  esac
done

mkdir -p "$STATE_DIR" "$(dirname "$LOG_FILE")"
touch "$LOG_FILE" && chmod 0640 "$LOG_FILE"
# everything below goes to the log file and to the journal/console
exec > >(tee -a "$LOG_FILE") 2>&1

STEP="init"
log() { printf '%s [facedoor-firstboot] %s\n' "$(date -Is)" "$*"; }
fail() {
  local code="$1"; shift
  log "FAILED at step '$STEP': $*"
  printf 'time=%s\nstep=%s\ncode=%s\nreason=%s\n' "$(date -Is)" "$STEP" "$code" "$*" >"$FAIL_MARKER"
  log "the unit stays enabled and retries on the next boot; manual retry: sudo /usr/local/sbin/facedoor-firstboot"
  exit "$code"
}

if [[ $EUID -ne 0 ]]; then
  echo "must run as root" >&2
  exit 1
fi

if [[ -f "$DONE_MARKER" && $FORCE -eq 0 ]]; then
  log "already done ($(head -n1 "$DONE_MARKER" 2>/dev/null)); nothing to do (use --force to re-run)"
  exit 0
fi

exec 9>"$LOCK_FILE"
if ! flock -n 9; then
  log "another instance is running; exiting"
  exit 0
fi

# ---------------------------------------------------------------------------------------------
# settings: parsed as KEY=VALUE (never 'source'd) and validated
# ---------------------------------------------------------------------------------------------
STEP="settings"
FACEDOOR_USER=""
FACEDOOR_DIR="/opt/facedoor"
FACEDOOR_BUNDLE="/boot/firmware/facedoor-bundle.tar.gz"
FACEDOOR_ENABLE_SERVICE=0
FACEDOOR_DOWNLOAD_MODELS=1
FACEDOOR_SET_PI_MODE=1
FACEDOOR_NET_TIMEOUT=900
[[ -f "$ENV_FILE" ]] || fail 2 "settings file $ENV_FILE missing (cloud-init write_files did not run?)"
while IFS= read -r line || [[ -n "$line" ]]; do
  line="${line%$'\r'}"
  [[ -z "$line" || "$line" == \#* ]] && continue
  key="${line%%=*}"
  val="${line#*=}"
  case "$key" in
    FACEDOOR_USER|FACEDOOR_DIR|FACEDOOR_BUNDLE|FACEDOOR_ENABLE_SERVICE|FACEDOOR_DOWNLOAD_MODELS|\
FACEDOOR_SET_PI_MODE|FACEDOOR_NET_TIMEOUT)
      printf -v "$key" '%s' "$val" ;;
    *) log "ignoring unknown setting '$key'" ;;
  esac
done <"$ENV_FILE"

[[ "$FACEDOOR_USER" =~ ^[a-z_][a-z0-9_-]{0,31}$ && "$FACEDOOR_USER" != "root" ]] \
  || fail 2 "invalid FACEDOOR_USER '$FACEDOOR_USER'"
[[ "$FACEDOOR_DIR" =~ ^/([A-Za-z0-9._-]+/)*[A-Za-z0-9._-]+$ && "$FACEDOOR_DIR" != *..* ]] \
  || fail 2 "FACEDOOR_DIR must be an absolute ASCII path: '$FACEDOOR_DIR'"
case "$FACEDOOR_DIR" in /|/usr|/etc|/boot|/home|/var|/opt|/root|/bin|/sbin|/lib) \
  fail 2 "refusing FACEDOOR_DIR=$FACEDOOR_DIR" ;; esac
[[ "$FACEDOOR_BUNDLE" =~ ^/[A-Za-z0-9._/-]+$ ]] || fail 2 "invalid FACEDOOR_BUNDLE '$FACEDOOR_BUNDLE'"
for k in FACEDOOR_ENABLE_SERVICE FACEDOOR_DOWNLOAD_MODELS FACEDOOR_SET_PI_MODE; do
  [[ "${!k}" == 0 || "${!k}" == 1 ]] || fail 2 "$k must be 0 or 1 (got '${!k}')"
done
[[ "$FACEDOOR_NET_TIMEOUT" =~ ^[0-9]{1,5}$ ]] || fail 2 "invalid FACEDOOR_NET_TIMEOUT"
id "$FACEDOOR_USER" >/dev/null 2>&1 || fail 2 "user '$FACEDOOR_USER' does not exist (cloud-init users: failed?)"

log "start: user=$FACEDOOR_USER dir=$FACEDOOR_DIR bundle=$FACEDOOR_BUNDLE service=$FACEDOOR_ENABLE_SERVICE" \
    "models=$FACEDOOR_DOWNLOAD_MODELS pi_mode=$FACEDOOR_SET_PI_MODE"
rm -f "$FAIL_MARKER"

# ---------------------------------------------------------------------------------------------
# 1. network
# ---------------------------------------------------------------------------------------------
STEP="network"
deadline=$(( $(date +%s) + FACEDOOR_NET_TIMEOUT ))
until getent ahosts ports.ubuntu.com >/dev/null 2>&1 && getent ahosts pypi.org >/dev/null 2>&1; do
  if (( $(date +%s) >= deadline )); then
    fail 5 "no network/DNS after ${FACEDOOR_NET_TIMEOUT}s (check cable / Wi-Fi in network-config)"
  fi
  sleep 5
done
log "network OK"

# ---------------------------------------------------------------------------------------------
# 2. bundle checksum
# ---------------------------------------------------------------------------------------------
STEP="verify-bundle"
SUM_FILE="$FACEDOOR_BUNDLE.sha256"
[[ -f "$FACEDOOR_BUNDLE" ]] || fail 3 "bundle $FACEDOOR_BUNDLE not found"
[[ -f "$SUM_FILE" ]] || fail 3 "checksum file $SUM_FILE not found"
expected="$(awk 'NR==1{print tolower($1)}' "$SUM_FILE")"
[[ "$expected" =~ ^[0-9a-f]{64}$ ]] || fail 3 "malformed checksum file $SUM_FILE"
actual="$(sha256sum "$FACEDOOR_BUNDLE" | awk '{print $1}')"
[[ "$actual" == "$expected" ]] || fail 3 "bundle SHA256 mismatch: got $actual expected $expected (re-stage the card)"
log "bundle sha256 OK ($actual)"

# ---------------------------------------------------------------------------------------------
# 3. extract
# ---------------------------------------------------------------------------------------------
STEP="extract"
if [[ -f "$FACEDOOR_DIR/$STAMP_NAME" && "$(cat "$FACEDOOR_DIR/$STAMP_NAME")" == "$actual" \
      && -f "$FACEDOOR_DIR/deploy/install_rpi.sh" ]]; then
  log "$FACEDOOR_DIR already holds this bundle; skipping extraction"
else
  # all members must be relative paths under facedoor/ (no absolute paths, no '..')
  if tar -tzf "$FACEDOOR_BUNDLE" | grep -Ev '^facedoor/' | grep -q .; then
    fail 3 "bundle contains entries outside facedoor/"
  fi
  if tar -tzf "$FACEDOOR_BUNDLE" | grep -Eq '(^|/)\.\.(/|$)'; then
    fail 3 "bundle contains '..' entries"
  fi
  parent="$(dirname "$FACEDOOR_DIR")"
  mkdir -p "$parent"
  staging="$(mktemp -d "$parent/.facedoor-staging.XXXXXX")" || fail 4 "mktemp failed in $parent"
  trap 'rm -rf "$staging"' EXIT
  tar -xzf "$FACEDOOR_BUNDLE" -C "$staging" --no-same-owner || fail 4 "tar extraction failed"
  [[ -f "$staging/facedoor/MANIFEST.sha256" ]] || fail 3 "MANIFEST.sha256 missing in bundle"
  (cd "$staging/facedoor" && sha256sum --quiet -c MANIFEST.sha256) || fail 3 "MANIFEST.sha256 verification failed"
  if [[ -e "$FACEDOOR_DIR" ]]; then
    # previous install of a different bundle: keep device-local data, move the rest aside
    backup="$FACEDOOR_DIR.bak-$(date +%Y%m%d%H%M%S)"
    log "existing $FACEDOOR_DIR moved to $backup (configs/local.yaml, data/, models/ are carried over)"
    mv "$FACEDOOR_DIR" "$backup" || fail 4 "cannot move existing $FACEDOOR_DIR"
    for keep in configs/local.yaml data models logs; do
      if [[ -e "$backup/$keep" ]]; then
        mkdir -p "$staging/facedoor/$(dirname "$keep")"
        cp -a "$backup/$keep" "$staging/facedoor/$(dirname "$keep")/" || true
      fi
    done
  fi
  mv "$staging/facedoor" "$FACEDOOR_DIR" || fail 4 "cannot move extracted tree to $FACEDOOR_DIR"
  printf '%s\n' "$actual" >"$FACEDOOR_DIR/$STAMP_NAME"
  rm -rf "$staging"
  trap - EXIT
  log "extracted to $FACEDOOR_DIR"
fi
chown -R "$FACEDOOR_USER":"$FACEDOOR_USER" "$FACEDOOR_DIR" || fail 4 "chown failed"

# ---------------------------------------------------------------------------------------------
# 4. hardware mode (written only if configs/local.yaml does not exist yet)
# ---------------------------------------------------------------------------------------------
STEP="local-config"
LOCAL_CFG="$FACEDOOR_DIR/configs/local.yaml"
if [[ ! -f "$LOCAL_CFG" ]]; then
  if [[ "$FACEDOOR_SET_PI_MODE" == 1 ]]; then mode=pi; else mode=mock; fi
  cat >"$LOCAL_CFG" <<EOF
# Device-local overrides written by facedoor-firstboot (see docs/PORTING.md).
hardware:
  mode: $mode
  # solenoid_active_high: false   # most opto-isolated relay modules are active-LOW: check deploy/WIRING.md
camera:
  source: "/dev/video0"
EOF
  chown "$FACEDOOR_USER":"$FACEDOOR_USER" "$LOCAL_CFG"
  log "wrote $LOCAL_CFG (hardware.mode=$mode)"
else
  log "$LOCAL_CFG exists; left unchanged"
fi

# ---------------------------------------------------------------------------------------------
# 5. install (idempotent; never started here)
# ---------------------------------------------------------------------------------------------
STEP="install_rpi"
args=(--user "$FACEDOOR_USER")
[[ "$FACEDOOR_ENABLE_SERVICE" == 1 ]] || args+=(--no-service)
[[ "$FACEDOOR_DOWNLOAD_MODELS" == 1 ]] || args+=(--no-models)
log "running $FACEDOOR_DIR/deploy/install_rpi.sh ${args[*]}"
export DEBIAN_FRONTEND=noninteractive
# apt may be locked by unattended-upgrades right after first boot: wait up to 10 minutes
for _ in $(seq 1 120); do
  if ! fuser /var/lib/dpkg/lock-frontend /var/lib/apt/lists/lock >/dev/null 2>&1; then break; fi
  sleep 5
done
bash "$FACEDOOR_DIR/deploy/install_rpi.sh" "${args[@]}" || fail 6 "install_rpi.sh exited with $?"

# ---------------------------------------------------------------------------------------------
# 6. done
# ---------------------------------------------------------------------------------------------
STEP="finish"
printf '%s bundle=%s dir=%s\n' "$(date -Is)" "$actual" "$FACEDOOR_DIR" >"$DONE_MARKER"
systemctl disable facedoor-firstboot.service >/dev/null 2>&1 || true
log "DONE. Outputs were not driven by this script."
if [[ "$FACEDOOR_ENABLE_SERVICE" == 1 ]]; then
  log "facedoor.service is enabled and starts on the next boot (sudo reboot), or: sudo systemctl start facedoor"
else
  log "service not installed (FACEDOOR_ENABLE_SERVICE=0); see docs/PORTING.md for manual start"
fi
log "check outputs first: $FACEDOOR_DIR/.venv/bin/python $FACEDOOR_DIR/scripts/hw_selftest.py --mode pi"
exit 0
